"""Writes docs/R2_SUMMARY.md from results/results_robot.json, results/r2_checks.json and results/trace_merchant_default.json."""
from __future__ import annotations


def build(R: str, DOCS: str) -> None:
    """R: results directory. DOCS: output directory."""
    import json, os, re

    D = json.load(open(os.path.join(R, "results_robot.json")))
    K = json.load(open(os.path.join(R, "r2_checks.json")))
    T = json.load(open(os.path.join(R, "trace_merchant_default.json")))
    C = ["fixed", "merchant", "ppa", "capped"]
    S = list(D["_meta"]["settings"]); FAC = D["_meta"]["factors"]; V = D["_verdict_H_R2"]
    LABEL = {"default": "default", "night240": "night 240 min", "night480": "night 480 min", "service15": "service 15 min", "service40": "service 40 min",
             "speed0.25": "speed 0.25 m/s", "speed1.0": "speed 1.0 m/s", "battery6": "battery 6 rows", "battery10": "battery 10 rows",
             "avail0.9": "availability 0.9", "avail0.8": "availability 0.8"}
    ci = lambda x: f"{x['mean']:+.0f} [{x['lo']:+.0f}, {x['hi']:+.0f}]"
    side = lambda x: "CI > 0" if x["lo"] > 0 else "CI < 0" if x["hi"] < 0 else "CI spans 0"
    voc = lambda s, c: D[f"{s}|{c}"]["metrics"]["value_of_cleaning"]["mean"]
    ratio = lambda s, c: voc(s, c) / voc("default", c)
    cpu = lambda f: float(re.search(r"User time \(seconds\): ([\d.]+)", open(os.path.join(R, f)).read()).group(1))

    L = []
    w = L.append
    w("# E1 Phase R2: robot capability sweep and mission traces\n")
    w("**EXTENSION / DESCRIPTIVE.** Generated markets, four contracts, the 50 test seeds. Pre-registration: `docs/EXPERIMENT_LOG.md`, \"Phase R2\", committed alone as 427dcfd "
      "before any R2 run. Generated by `src/make_r2_summary.py`. Section 6 is unregistered and does not enter the verdict.\n")
    w("## Summary\n")
    w(f"- **H-R2: {V['verdict']}** (rule applied as written). The difference in advantage is at or below 0 in {V['mean_nonpos']} of 12 cells; {V['ci_wholly_above']} interval lies wholly above 0 and {V['ci_wholly_below']} wholly below.")
    lo = min((ratio(s, c), s, c) for s in S for c in C)
    w(f"- **Sufficient robot: not reached.** No tested setting takes the value of cleaning below 90% of default in any contract. The lowest is {100 * lo[0]:.1f}% ({LABEL[lo[1]]}, {lo[2]}).")
    u = K["use"]["default|merchant"]
    w(f"- **Why capacity matters so little** (section 6). Missions are full ({100 * u['share_full']:.0f}% fill the night at default, merchant), but the robot uses only {100 * u['night_use_year']:.0f}% of its yearly night time. Tighter limits mainly split sweeps into more missions, which costs more and leads to somewhat fewer row cleanings, while the robot stays idle most nights.\n")

    w("## 1. H-R2 verdict (EXTENSION)\n")
    w("Advantage = planner minus the training-selected best baseline, per seed. The cell value is the advantage at the tight setting minus the advantage at default, paired over the same 50 seeds (USD/yr, mean and 95% t-interval).\n")
    w("| tight setting | contract | advantage tight | advantage default | difference [95% CI] | side | baseline tight / default |\n|---|---|---|---|---|---|---|")
    for k, x in V["cells"].items():
        s, c = k.split("|")
        w(f"| {LABEL[s]} | {c} | {x['adv_tight']:+.0f} | {x['adv_default']:+.0f} | {ci(x)} | {side(x)} | {x['bestbase_tight']} / {x['bestbase_default']} |")
    w(f"\nRule: SUPPORTED needs at least 6 intervals wholly above 0 and none below 0: there are {V['ci_wholly_above']} and {V['ci_wholly_below']}. NOT SUPPORTED needs the difference at or below 0 in at least 6: there are {V['mean_nonpos']}. **Verdict: {V['verdict']}.**\n")

    w("## 2. Sweep table (EXTENSION)\n")
    w("Planner results, USD/yr unless stated, each cell retuned. Value of cleaning is planner net value over no cleaning. Rows/night is what one mission reaching row 40 can clean.\n")
    w("| setting | contract | rows/night | best baseline | value of cleaning | % of default | planner - best baseline | planner - FT | recovered MWh | row cleanings | missions |\n|---|---|---|---|---|---|---|---|---|---|---|")
    for s in S:
        for c in C:
            r = D[f"{s}|{c}"]; m = r["metrics"]
            w(f"| {LABEL[s]} | {c} | {r['rows_per_night']} | {r['best_baseline']} | {m['value_of_cleaning']['mean']:.0f} | {100 * ratio(s, c):.1f} | {ci(m['planner_bestbase'])} | {ci(m['planner_ft'])} | {m['recovered_mwh']['mean']:.1f} | {m['row_cleanings']['mean']:.0f} | {m['missions']['mean']:.0f} |")

    w("\n## 3. Sufficient-robot points (DESCRIPTIVE)\n")
    w("Value of cleaning at the weakest tested level of each factor, as % of default. The pre-registered point is where this drops below 90%.\n")
    w("| contract | value of cleaning at default | night 240 | service 40 | speed 0.25 | battery 6 | availability 0.8 | sufficient-robot point |\n|---|---|---|---|---|---|---|---|")
    for c in C:
        w(f"| {c} | {voc('default', c):.0f} | " + " | ".join(f"{100 * ratio(s, c):.1f}" for s in ("night240", "service40", "speed0.25", "battery6", "avail0.8")) + " | below the tested range |")
    w("\nThe point is below the weakest tested level of every factor in all four contracts, so the sweep gives only an upper bound. Section 6 has an unregistered look lower down.\n")

    st = T["stats"]
    w("## 4. Trace statistics (DESCRIPTIVE)\n")
    w(f"Merchant, default robot, seed {T['seed']} (planner net {T['planner_net']:.0f} USD; the median of the 50 seeds is {T['median_net_all_seeds']:.0f}, midway between two seeds, so the lower one is used). `results/trace_merchant_default.json`, `results/figures/fig_mission.pdf`.\n")
    w(f"| statistic | seed {T['seed']} | all 50 seeds |\n|---|---|---|")
    m0 = D["default|merchant"]["metrics"]
    w(f"| missions per year | {st['missions']} | {m0['missions']['mean']:.1f} |")
    w(f"| mean rows per mission | {st['mean_rows_per_mission']:.1f} | {u['rows_per_mission']:.1f} |")
    w(f"| mean night use per mission | {100 * st['mean_night_use']:.1f}% | {100 * u['night_use_year'] / (m0['missions']['mean'] / 365):.1f}% (ratio of means) |")
    w(f"| share of all night time used | {100 * st['mean_night_use'] * st['share_nights_worked']:.1f}% | {100 * u['night_use_year']:.1f}% |")
    w(f"| share of nights the robot works | {100 * st['share_nights_worked']:.1f}% | {100 * m0['missions']['mean'] / 365:.1f}% |")
    n = T["night"]
    w(f"\nThe shown night precedes production day {n['date']} ({len(n['rows'])} rows, back at the dock after {n['end_min']:.0f} of {T['robot']['night_min']:.0f} min). It is the only mission of that year on a night with closed rows ({st['missions_on_closed_nights']} of {st['missions']}), chosen so the closures are visible. "
      "Its alternate-row pattern is therefore not typical: most missions that year clean a contiguous block. On that night no closed row met the cleaning test "
      f"({st['rows_skipped_closed']} rows skipped); rows 2-26 had been cleaned the night before.\n")

    w("## 5. Deviations and interpretation choices\n")
    for i, t in enumerate([
        "The brief says 13 settings; the pre-registered factor list has 11 distinct settings, so 44 cells were run (logged under R2 blockers).",
        "The pre-registration header carries the date given in the brief, 2026-10-28, verbatim. It was committed on 2026-11-04 (machine clock), still before any R2 run; the git history is the record.",
        "\"Below 0 in none\" is read as no interval wholly below 0, the R1 convention; reading it as no negative mean changes nothing, as SUPPORTED fails either way. \"At or below 0 in at least 6\" is read as the mean, also the R1 convention and the plain sense of \"it\". **This reading decides the verdict:** if it meant intervals wholly below 0, the count would be 5 of 12 and the verdict PARTIAL.",
        "\"Best baseline\" means fixed, threshold or econ, as in R1. FT is reported separately.",
        "The simulator has no visit order or clock, only a mission duration. The mission log uses the one order consistent with that duration (ascending rows out, straight return) and starts each mission when the night window opens. Times are minutes from that opening, not clock times.",
        "The brief says dock at row 1. `sim.mission_time` charges (index + 1) pitches, so the dock sits 10 m before row 1. The export and the figure follow the simulator. Row length is not modelled and is schematic in the figure.",
        "Rows are 1-40 in the trace and figures, 0-39 in `sim.py`. The `blackouts` mask closes 0-based odd indices, so even-numbered rows 2-40 close.",
        "With 50 seeds the median is between two seeds; the lower one is used. The night rule (at least 4 rows, on a closed night, size nearest the median mission) was set after seeing that seed's mission list, so it is a presentation choice.",
        "The soiling ratio exported for a night is the value when that night's decision is taken. The true ratio is exported too.",
        "The value of cleaning is on a separate small axis row, not a second y-scale. Node is not installed, so the skill's palette validator did not run; an equivalent Python OKLab check of the four Okabe-Ito colours gave a minimum separation of 16.4 normal, 9.6 protan, 7.6 deutan, 8.6 tritan. The 7.6 is acceptable only with the line styles and markers used.",
        "Intervals are over test seeds with tuned parameters held fixed, so they exclude tuning noise (section 6 sizes it). Tuning uses 5 train seeds, as in all earlier phases.",
        "`battery_rows` acts in `sim.pack`, not in the exact MILP in `src/exact.py`, which R2 does not use. `src/checks.py` now checks it. README's fixed test count was removed.",
    ], 1):
        w(f"{i}. {t}")

    w("\n## 6. Checks of surprises (UNREGISTERED DIAGNOSTIC, `results/r2_checks.json`)\n")
    b = [K["frozen"][f"{s}|fixed"]["planner_threshold"]["mean"] for s in FAC["battery"]]
    bm = [K["frozen"][f"{s}|merchant"]["planner_threshold"]["mean"] for s in FAC["battery"]]
    br = [D[f"{s}|fixed"]["metrics"]["planner_bestbase"]["mean"] for s in FAC["battery"]]
    w(f"- **The advantage is not monotonic in capacity.** Fixed tariff, battery 6 / 10 / unlimited: {br[0]:+.0f}, {br[1]:+.0f}, {br[2]:+.0f} retuned. With default parameters frozen it rises steadily: {b[0]:+.0f}, {b[1]:+.0f}, {b[2]:+.0f}, so this kink comes from parameter selection. Merchant stays flat within noise when frozen ({bm[0]:+.0f}, {bm[1]:+.0f}, {bm[2]:+.0f}).")
    rt = K["retune"]
    w("- **Tuning noise.** Repeating default and tight cells with other train seeds: " + "; ".join(f"{k}: {v['mean_nonpos']}/12 means <= 0, {v['ci_wholly_above']} above, {v['ci_wholly_below']} below" for k, v in rt.items()) + ". The rule would give NOT SUPPORTED each time, only just for train1010. Individual cells move, though, so cell-level claims are weaker than the intervals suggest.")
    keys = [f"{s}|{c}" for s in D["_meta"]["tight"] for c in C]
    allm = [[V["cells"][k]["mean"] for k in keys]] + [v["means"] for v in rt.values()]
    pos = {c: sum(m[i] > 0 for m in allm for i, k in enumerate(keys) if k.endswith("|" + c)) for c in C}
    w(f"- **Contract pattern.** Across the 4 train sets x 3 tight settings (12 values per contract), the difference is positive in {pos['ppa']}/12 for PPA, {pos['capped']}/12 for capped, {pos['fixed']}/12 for fixed and {pos['merchant']}/12 for merchant. So the sign points up under PPA and down under the export cap whichever train seeds are used; fixed and merchant are mostly negative, but their signs vary with the train seeds.")
    th = K["tally_threshold_held"]
    w(f"- **The one interval above 0** (battery 6, PPA) is also a cell where the baseline switched to econ. Holding threshold as the baseline in every cell, it stays above 0 at {ci(th['cells']['battery6|ppa'])}, and the tally is unchanged ({th['mean_nonpos']} at or below 0, {th['ci_wholly_above']} above, {th['ci_wholly_below']} below).")
    fr = K["frozen"]
    w(f"- **Availability looks inert.** Merchant value of cleaning is {voc('avail0.8', 'merchant'):.0f} at 0.8 against {voc('default', 'merchant'):.0f}. Frozen parameters agree ({fr['avail0.8|merchant']['value_of_cleaning']['mean']:.0f}), so retuning does not hide a loss. Tests confirm no mission falls on a down night. A likely reason, not tested separately: the robot works on only 9% of nights, so a down night usually delays a mission by about a night. It does respond lower down: {100 * K['low']['avail0.25|merchant']['voc_ratio']:.1f}% at availability 0.25.")
    dc = K["decomp"]["battery6|merchant"]
    w(f"- **Mechanism of the small losses.** Merchant, battery 6 against default: value of cleaning {dc['d_voc']:+.0f} = revenue {dc['d_revenue']:+.0f}, cleaning-cost saving {-dc['d_clean']:+.0f}, extra mission cost {-dc['d_mission']:+.0f}. Missions rise from {m0['missions']['mean']:.0f} to {D['battery6|merchant']['metrics']['missions']['mean']:.0f} and row cleanings fall. Row demand is about {m0['row_cleanings']['mean']:.0f} a year against a capacity near {13 * 365}.")
    lw = K["low"]
    w("- **Below the tested range** (retuned, value of cleaning as % of default):\n")
    w("| contract | battery 1 | battery 2 | battery 3 | battery 4 | availability 0.5 | availability 0.25 |\n|---|---|---|---|---|---|---|")
    for c in C:
        w(f"| {c} | " + " | ".join(f"{100 * lw[f'{s}|{c}']['voc_ratio']:.1f}" for s in ("battery1", "battery2", "battery3", "battery4", "avail0.5", "avail0.25")) + " |")
    w("\n  On this unregistered evidence the 90% point lies between 1 and 2 rows per mission in every contract, and availability does not reach it by 0.25.\n")
    w("## 7. Reproduction\n")
    w(f"`cd experiments && python robot_sweep.py && python mission_trace.py && python r2_checks.py`, then `python ../src/make_r2_figures.py` and `python ../src/make_r2_summary.py`. Sweep: {cpu('time_robot.txt'):.0f} s CPU, 24 workers. The default cells equal `results_rq1_decomp.json` rq1 exactly on every stored field. Pool(3) equals Pool(24) on avail0.8|merchant and battery6|ppa.")
    open(os.path.join(DOCS, "R2_SUMMARY.md"), "w").write("\n".join(L) + "\n")
